//! ⏱️ Bounds native fixture work independently from the exact issued currencies.
const LIMITS:(usize,usize,usize,usize,usize)=(16778496,16,256,1024,65537);
pub struct Work{turns:usize,idle:usize,maximum:usize}
impl Work{pub fn new()->Self{Self::for_rows(LIMITS.4)}pub fn for_rows(rows:usize)->Self{#[cfg(test)]validate_limits();let(_,_,per_row,fixed,maximum_rows)=LIMITS;assert!(rows<=maximum_rows,"native fixture row count exceeds its authored maximum");Self{turns:0,idle:0,maximum:work_limit(rows,per_row,fixed)}}pub fn observe(&mut self,unchanged:bool){self.turns=self.turns.checked_add(1).unwrap();self.idle=if unchanged{self.idle.checked_add(1).unwrap()}else{0};assert!(self.turns<self.maximum,"native fixture exceeded its checked row-scaled work");assert!(self.idle<LIMITS.1,"native fixture repeated an unchanged selected quote and empty receipt");}}
#[cfg(test)]
fn validate_limits()->(usize,usize,usize,usize,usize){static VALIDATED:std::sync::OnceLock<(usize,usize,usize,usize,usize)>=std::sync::OnceLock::new();*VALIDATED.get_or_init(||{let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let rows=fixture["maximumRows"].as_u64().unwrap()as usize;let per_row=fixture["turnsPerRow"].as_u64().unwrap()as usize;let fixed=fixture["fixedTurns"].as_u64().unwrap()as usize;let idle=fixture["maximumIdleTurns"].as_u64().unwrap()as usize;for row in fixture["cases"].as_array().unwrap(){let maximum=work_limit(row["rows"].as_u64().unwrap()as usize,per_row,fixed);let accepted=(row["turns"].as_u64().unwrap()as usize)<maximum&&(row["idle"].as_u64().unwrap()as usize)<idle;assert_eq!(accepted,row["accepted"].as_bool().unwrap());}for row in fixture["rowLimits"].as_array().unwrap(){let count=row["rows"].as_u64().unwrap()as usize;let actual=(count<=rows).then(||work_limit(count,per_row,fixed));assert_eq!(actual,row["maximum"].as_u64().map(|n|n as usize));}let actual=(work_limit(rows,per_row,fixed),idle,per_row,fixed,rows);assert_eq!(actual,LIMITS);actual})}
fn work_limit(rows:usize,per_row:usize,fixed:usize)->usize{rows.checked_mul(per_row).and_then(|n|n.checked_add(fixed)).unwrap()}
